-- Studio Manager — Postgres (Supabase). Traduzido das migrations SQLite 0001–0009.
-- Aplicar no SQL Editor do Supabase (ou `npx drizzle-kit push` com DATABASE_URL).
-- Valores em centavos (BRL). Senhas: somente hash scrypt "scrypt$salt$hash" (ver lib/store.ts).
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE IF NOT EXISTS clients (id serial PRIMARY KEY, name text NOT NULL, phone text NOT NULL DEFAULT '', whatsapp text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', birth_date varchar(10), origin text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog_services (id serial PRIMARY KEY, name text NOT NULL, category varchar(30) NOT NULL, description text NOT NULL DEFAULT '', price integer NOT NULL DEFAULT 0, duration_min integer NOT NULL DEFAULT 60, payment_terms text NOT NULL DEFAULT '', responsible text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appointments (id serial PRIMARY KEY, title text NOT NULL, client_name text NOT NULL DEFAULT '', client_id integer, service_id integer, google_event_id text, origin varchar(20) NOT NULL DEFAULT 'studio', service_type varchar(30) NOT NULL, date varchar(10) NOT NULL, start_time varchar(5) NOT NULL, duration_min integer NOT NULL DEFAULT 60, status varchar(20) NOT NULL DEFAULT 'confirmado', location text NOT NULL DEFAULT '', responsible text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', payment_amount integer, payment_due_date varchar(10), payment_paid boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks (id serial PRIMARY KEY, title text NOT NULL, description text NOT NULL DEFAULT '', assignee text NOT NULL DEFAULT '', employee_id integer, priority varchar(10) NOT NULL DEFAULT 'media', client_id integer, service_id integer, due_date varchar(10), done boolean NOT NULL DEFAULT false, appointment_id integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS budgets (id serial PRIMARY KEY, client_id integer NOT NULL, discount integer NOT NULL DEFAULT 0, valid_until varchar(10), status varchar(20) NOT NULL DEFAULT 'rascunho', notes text NOT NULL DEFAULT '', appointment_id integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS budget_items (id serial PRIMARY KEY, budget_id integer NOT NULL, service_id integer, service_name text NOT NULL, unit_price integer NOT NULL DEFAULT 0, quantity integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS conversations (id serial PRIMARY KEY, client_id integer NOT NULL, date varchar(10) NOT NULL, channel varchar(20) NOT NULL DEFAULT 'whatsapp', summary text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client_files (id serial PRIMARY KEY, client_id integer NOT NULL, name text NOT NULL, kind text NOT NULL DEFAULT 'Documento', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contracts (id serial PRIMARY KEY, client_id integer NOT NULL, title text NOT NULL, status varchar(30) NOT NULL DEFAULT 'rascunho', amount integer, date varchar(10), notes text NOT NULL DEFAULT '', budget_id integer, template_id integer, category varchar(30), service_label text NOT NULL DEFAULT '', event_date varchar(10), location text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', current_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contract_templates (id serial PRIMARY KEY, category varchar(30) NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contract_versions (id serial PRIMARY KEY, contract_id integer NOT NULL, version integer NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', amount integer, event_date varchar(10), location text NOT NULL DEFAULT '', edited_by text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id serial PRIMARY KEY, client_id integer NOT NULL, contract_id integer, name text NOT NULL, kind varchar(30) NOT NULL DEFAULT 'outro', date varchar(10) NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_log (id serial PRIMARY KEY, direction varchar(20) NOT NULL DEFAULT 'bidirecional', created_count integer NOT NULL DEFAULT 0, updated_count integer NOT NULL DEFAULT 0, cancelled_count integer NOT NULL DEFAULT 0, errors text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_conflicts (id serial PRIMARY KEY, appointment_id integer, title text NOT NULL, google_event_id text, studio_date varchar(10) NOT NULL, studio_start_time varchar(5) NOT NULL, studio_duration_min integer NOT NULL DEFAULT 60, google_date varchar(10) NOT NULL, google_start_time varchar(5) NOT NULL, google_duration_min integer NOT NULL DEFAULT 60, status varchar(30) NOT NULL DEFAULT 'pendente', created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS installments (id serial PRIMARY KEY, client_id integer NOT NULL, client_name text NOT NULL DEFAULT '', budget_id integer, appointment_id integer, title text NOT NULL, service_name text NOT NULL DEFAULT '', kind varchar(20) NOT NULL DEFAULT 'integral', number integer NOT NULL DEFAULT 1, total_parts integer NOT NULL DEFAULT 1, due_date varchar(10) NOT NULL, amount integer NOT NULL DEFAULT 0, paid_amount integer NOT NULL DEFAULT 0, paid_date varchar(10), payment_method varchar(20), receipt_info text NOT NULL DEFAULT '', registered_by text NOT NULL DEFAULT '', cancelled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id serial PRIMARY KEY, description text NOT NULL, category varchar(20) NOT NULL DEFAULT 'outros', supplier text NOT NULL DEFAULT '', due_date varchar(10) NOT NULL, amount integer NOT NULL DEFAULT 0, paid_amount integer NOT NULL DEFAULT 0, paid_date varchar(10), payment_method varchar(20), receipt_info text NOT NULL DEFAULT '', registered_by text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', cancelled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS finance_history (id serial PRIMARY KEY, type varchar(20) NOT NULL, kind varchar(10) NOT NULL, installment_id integer, expense_id integer, description text NOT NULL, date varchar(10), amount integer, method varchar(20), detail text NOT NULL DEFAULT '', actor text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wa_conversations (id serial PRIMARY KEY, client_id integer, contact_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', status varchar(30) NOT NULL DEFAULT 'aguardando-atendimento', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wa_messages (id serial PRIMARY KEY, conversation_id integer NOT NULL, direction varchar(10) NOT NULL DEFAULT 'recebida', source varchar(10) NOT NULL DEFAULT 'manual', body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wa_suggestions (id serial PRIMARY KEY, conversation_id integer NOT NULL, message_id integer, client_id integer, title text NOT NULL DEFAULT '', date varchar(10), start_time varchar(5), duration_min integer NOT NULL DEFAULT 60, service_type varchar(30), service_id integer, service_label text NOT NULL DEFAULT '', intent varchar(20), status varchar(20) NOT NULL DEFAULT 'pendente', appointment_id integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employees (id serial PRIMARY KEY, name text NOT NULL, email text NOT NULL DEFAULT '', role varchar(20) NOT NULL DEFAULT 'atendimento', phone text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT true, password_hash text NOT NULL DEFAULT '', password_set_at timestamptz, password_set_by text NOT NULL DEFAULT '', custom_permissions text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS production_cards (id serial PRIMARY KEY, title text NOT NULL, client_id integer, client_name text NOT NULL DEFAULT '', service_id integer, service_label text NOT NULL DEFAULT '', service_type varchar(30), appointment_id integer, budget_id integer, stage varchar(40) NOT NULL DEFAULT 'solicitacao-recebida', responsible text NOT NULL DEFAULT '', employee_id integer, stage_due_date varchar(10), event_date varchar(10), amount integer, basis text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS system_activity (id serial PRIMARY KEY, actor text NOT NULL DEFAULT '', actor_employee_id integer, type varchar(20) NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS release_checks (id serial PRIMARY KEY, key text NOT NULL UNIQUE, area text NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', kind varchar(20) NOT NULL DEFAULT 'manual', status varchar(20) NOT NULL DEFAULT 'pendente', result text NOT NULL DEFAULT '', note text NOT NULL DEFAULT '', checked_by text NOT NULL DEFAULT '', sort integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sim_tests (id serial PRIMARY KEY, ok boolean NOT NULL DEFAULT false, summary text NOT NULL DEFAULT '', details text NOT NULL DEFAULT '', ran_by text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS publication_steps (id serial PRIMARY KEY, key text NOT NULL UNIQUE, scope varchar(20) NOT NULL DEFAULT 'app', title text NOT NULL, description text NOT NULL DEFAULT '', state varchar(20) NOT NULL DEFAULT 'pendente', note text NOT NULL DEFAULT '', sort integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activity_log (id serial PRIMARY KEY, client_id integer NOT NULL, text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_appointments_date ON appointments(date);
CREATE INDEX IF NOT EXISTS idx_installments_due ON installments(due_date);
CREATE INDEX IF NOT EXISTS idx_budgets_client ON budgets(client_id);
CREATE INDEX IF NOT EXISTS idx_production_stage ON production_cards(stage);
